1	import { redirect, notFound } from "next/navigation";
2	import { headers } from "next/headers";
3	
4	/**
5	 * Host gate: the admin portal is only reachable from the dedicated admin
6	 * hostname(s) in NXEON_ADMIN_HOSTS (comma-separated). On any other host — e.g.
7	 * the public nxeon.cloud — /admin 404s as if it doesn't exist. Empty/unset =
8	 * no host restriction (dev fallback). Returns true when access should be REFUSED.
9	 */
10	async function adminHostBlocked(): Promise<boolean> {
11	  const allow = (process.env.NXEON_ADMIN_HOSTS ?? "")
12	    .split(",").map((s) => s.trim().toLowerCase()).filter(Boolean);
13	  if (allow.length === 0) return false;
14	  const host = ((await headers()).get("host") ?? "").toLowerCase().split(":")[0];
15	  return !allow.includes(host);
16	}
17	import { realUser, impersonating } from "@/lib/auth";
18	import { isStaff, canAccessHref } from "@/lib/rbac";
19	import { db } from "@/lib/db";
20	import { getSetting, getSettingBool } from "@/lib/settings";
21	import { Shell, type NavSection } from "@/components/portal/Shell";
22	import { ADMIN_NAV } from "@/lib/admin-groups";
23	import { AdminSubTabs } from "@/components/admin/SubTabs";
24	import AdminChatNotifier from "@/components/admin/AdminChatNotifier";
25	
26	/** Loose sanity check for a literal IPv4/IPv6 address (no CIDR / ranges). */
27	function isPlainIp(s: string): boolean {
28	  return /^\d{1,3}(\.\d{1,3}){3}$/.test(s) || (s.includes(":") && /^[0-9a-fA-F:]+$/.test(s));
29	}
30	
31	/**
32	 * IP allow-list gate for /admin. `allowed_admin_ips` is a comma-separated list of
33	 * literal IPs; empty = no restriction. Fails OPEN (allows) when the list has no
34	 * parseable entries or the requester IP can't be determined, so a bad value can
35	 * never lock every admin out — only an exact match is ever enforced.
36	 * Returns true when access should be REFUSED.
37	 */
38	async function adminIpBlocked(): Promise<boolean> {
39	  const raw = await getSetting("allowed_admin_ips", "");
40	  const entries = raw.split(",").map((s) => s.trim()).filter(Boolean);
41	  if (entries.length === 0) return false; // no restriction configured
42	  const valid = entries.filter(isPlainIp);
43	  if (valid.length === 0) {
44	    console.warn("[admin-ip] allowed_admin_ips is set but has no valid IPs; failing open:", raw);
45	    return false; // malformed -> fail open
46	  }
47	  const hdrs = await headers();
48	  // Trust nginx's X-Real-IP ($remote_addr), which the client cannot forge. Fall
49	  // back to the LAST X-Forwarded-For hop (the one our proxy appended), never the
50	  // client-supplied leftmost entry.
51	  const xff = (hdrs.get("x-forwarded-for") ?? "").split(",").map((s) => s.trim()).filter(Boolean);
52	  const ip = hdrs.get("x-real-ip")?.trim() || xff[xff.length - 1] || "";
53	  if (!ip) {
54	    console.warn("[admin-ip] could not determine requester IP; failing open");
55	    return false;
56	  }
57	  return !valid.includes(ip);
58	}
59	
60	export default async function AdminLayout({ children }: { children: React.ReactNode }) {
61	  // Wrong host (e.g. public nxeon.cloud) → 404, so /admin isn't reachable there.
62	  if (await adminHostBlocked()) notFound();
63	
64	  const user = await realUser();
65	  if (!user) redirect("/login");
66	  if (!isStaff(user.role)) redirect("/dashboard");
67	  const imp = await impersonating();
68	  if (imp) redirect("/dashboard"); // exit impersonation before using admin tools
69	
70	  // IP allow-list: refuse admin access from an IP that isn't explicitly allowed.
71	  if (await adminIpBlocked()) {
72	    return (
73	      <main
74	        style={{
75	          minHeight: "100vh",
76	          display: "flex",
77	          flexDirection: "column",
78	          alignItems: "center",
79	          justifyContent: "center",
80	          gap: "0.75rem",
81	          padding: "2rem",
82	          textAlign: "center",
83	        }}
84	      >
85	        <h1 style={{ fontSize: "1.5rem", fontWeight: 600 }}>Access restricted</h1>
86	        <p style={{ maxWidth: "32rem", opacity: 0.8 }}>
87	          The admin console isn&apos;t available from your current network.
88	        </p>
89	      </main>
90	    );
91	  }
92	
93	  // Staff 2FA enforcement: when enabled, staff without TOTP must set it up before
94	  // using admin tools. Redirect (don't hard-fail) to their security settings so
95	  // they can enroll, then come back.
96	  if ((await getSettingBool("enforce_staff_2fa", false)) && !user.totpEnabled) {
97	    redirect("/dashboard/settings?require2fa=1");
98	  }
99	
100	  // Filter every entry's members down to what this role can access, drop entries
101	  // that end up empty, then drop sections that end up empty. An entry always
102	  // links to (and its sub-tab bar always starts at) its first *accessible*
103	  // member, so no role is ever handed a link that just bounces it to /admin.
104	  const visibleSections = ADMIN_NAV.map((section) => ({
105	    ...section,
106	    entries: section.entries
107	      .map((entry) => ({
108	        ...entry,
109	        tabs: entry.tabs.filter((tab) => canAccessHref(user.role, tab.href)),
110	      }))
111	      .filter((entry) => entry.tabs.length > 0),
112	  })).filter((section) => section.entries.length > 0);
113	
114	  // Flat list of every href this role may reach — handed to <AdminSubTabs /> so
115	  // the in-page tab bars hide the same members the sidebar does.
116	  const allowedHrefs = visibleSections.flatMap((s) =>
117	    s.entries.flatMap((e) => e.tabs.map((t) => t.href))
118	  );
119	
120	  const notifications = await db.notification.findMany({
121	    where: { userId: user.id },
122	    orderBy: { createdAt: "desc" },
123	    take: 15,
124	  });
125	
126	  // Attention-count badges for the sidebar. Each count fails soft (→ 0) so a
127	  // missing model/table can never break the admin layout.
128	  const soft = (p: Promise<number>) => p.catch(() => 0);
129	  const [chatUnread, ticketsAwaiting, abuseOpen, feedbackNew, improvementsProposed] = await Promise.all([
130	    // Live chat: conversations flagged unread for agents (same "needs a reply"
131	    // signal the chat inbox sorts/counts by — ChatConversation.unreadForAgent).
132	    soft(db.chatConversation.count({ where: { unreadForAgent: true } })),
133	    // Support desk: tickets awaiting a staff reply (open + customer replies),
134	    // matching the "Awaiting staff" stat on /admin/support.
135	    soft(db.ticket.count({ where: { status: { in: ["OPEN", "CUSTOMER_REPLY"] } } })),
136	    // Abuse queue: alerts still OPEN.
137	    soft(db.abuseAlert.count({ where: { status: "OPEN" } })),
138	    // Feedback: new (untriaged) reports.
139	    soft(db.feedback.count({ where: { status: "NEW" } })),
140	    // Improvements board: proposals awaiting the owner's approve/decline.
141	    soft(db.improvement.count({ where: { status: "PROPOSED" } })),
142	  ]);
143	
144	  // Per-route attention counts, unchanged in meaning from the flat sidebar.
145	  const badges: Record<string, number> = {
146	    "/admin/chat": chatUnread,
147	    "/admin/support": ticketsAwaiting,
148	    "/admin/abuse": abuseOpen,
149	    "/admin/feedback": feedbackNew,
150	    "/admin/improvements": improvementsProposed,
151	  };
152	  // Build the sidebar: one icon'd row per top-level ENTRY, grouped into labelled
153	  // sections. Secondary members ride along as `children` — the sidebar never
154	  // expands them (they're the page's sub-tabs), but they keep the parent row
155	  // highlighted while you're on one and keep ⌘K able to reach every route.
156	  // Attention counts ROLL UP: an entry shows the sum of its members' badges, and
157	  // <AdminSubTabs /> repeats each member's own count on its tab.
158	  const nav: NavSection[] = visibleSections.map((section) => ({
159	    label: section.label,
160	    items: section.entries.map((entry) => {
161	      const rollup = entry.tabs.reduce((sum, tab) => sum + (badges[tab.href] ?? 0), 0);
162	      return {
163	        label: entry.label,
164	        href: entry.tabs[0].href,
165	        icon: entry.icon,
166	        badge: rollup > 0 ? rollup : undefined,
167	        children: entry.tabs.map((tab) => ({
168	          label: tab.label,
169	          href: tab.href,
170	          badge: badges[tab.href] > 0 ? badges[tab.href] : undefined,
171	        })),
172	      };
173	    }),
174	  }));
175	
176	  return (
177	    <Shell
178	      nav={nav}
179	      tag="ops"
180	      user={{ name: user.name, email: user.email, role: user.role, balanceCents: user.balanceCents }}
181	      notifications={notifications.map((n) => ({
182	        id: n.id,
183	        title: n.title,
184	        body: n.body,
185	        href: n.href,
186	        readAt: n.readAt ? n.readAt.toISOString() : null,
187	        createdAt: n.createdAt.toISOString(),
188	      }))}
189	    >
190	      {/* Sub-navigation for the consolidated entries, mounted once here so every
191	          grouped page gets its tab bar without per-page wiring. Renders nothing
192	          for single-member entries. */}
193	      <AdminSubTabs badges={badges} allowed={allowedHrefs} />
194	      {/* Browser sound + Web Notification when a new live-chat message arrives
195	          while an admin tab is open. Self-contained + defensive; renders null. */}
196	      <AdminChatNotifier />
197	      {children}
198	    </Shell>
199	  );
200	}
